        "description": "中部大组团，正在打开超级机场时代。近日，《邮政业发展“十五五”规划》印发，提出要完善国家邮政快递枢纽，提升枢纽航空转运能力。与之前某个机场的“单兵作战”不同，本轮航空枢纽建设更聚焦区域内机场的抱团发展。其中，华中囊括武汉、鄂州、郑州、长沙。这一次，中部如何抢占先机？",
